#[test]
fn listed_source_tree_recipes_match_vendored_catalogued() {
    let listed: Vec<String> = SOURCE_TREE_RECIPES
        .iter()
        .map(|rel| (*rel).to_string())
        .collect();
    assert_eq!(common::catalogued_source_tree_recipe_rels(), listed);
}

#[test]
